window.docContents[139].resolve({"/Abstraction/Return/#Core-C______--Abstraction--Return":{"contents":"The return yields the control , which Seq-Ret and While-Ret propagate up to the call. The type of the expression is the return type  of the enclosing function.The implementations are partial, so Lean records opaque constants that carry the type and not the body, and no property of them is proved here.\n\n","context":"Core C++\u0009Abstraction","header":"5.4. Return","id":"/Abstraction/Return/#Core-C______--Abstraction--Return"}});